package contexts_test

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// Legacy contexts.json with a login but a CLEARED current_context — what a
// failed promoteNextLogin leaves behind. Migration must not delete the file
// while leaving that login's credentials stranded in the keychain.
func TestProbe_MigrationWithClearedCurrentContext(t *testing.T) {
	cfgDir := t.TempDir()
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	svc := tokenstore.CoreKeyringService("https://core.example")
	for _, seed := range []struct{ service, value string }{
		{svc, "access-token"},
		{tokenstore.RefreshService(svc), "refresh-token"},
		{tokenstore.JurisdictionService("https://eu.example"), "juris-token"},
	} {
		if err := tokenstore.Set(seed.service, "alice", seed.value); err != nil {
			t.Fatalf("seed %s: %v", seed.service, err)
		}
	}

	data, err := json.Marshal(contexts.File{
		CurrentContext: "",
		Contexts: []*contexts.Context{{
			Name:                  "core.example",
			CoreURL:               "https://core.example",
			Handle:                "alice",
			KeychainService:       svc,
			JurisdictionAudiences: []string{"https://eu.example"},
		}},
	})
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	legacyPath := filepath.Join(cfgDir, "contexts.json")
	if err := os.WriteFile(legacyPath, data, 0o600); err != nil {
		t.Fatalf("write legacy: %v", err)
	}

	if _, err := contexts.Load(cfgDir); err != nil {
		t.Fatalf("Load: %v", err)
	}
	if _, err := os.Stat(legacyPath); err == nil {
		t.Error("contexts.json should be removed once migration has run")
	}

	for _, probe := range []struct{ label, service string }{
		{"access", svc},
		{"refresh", tokenstore.RefreshService(svc)},
		{"jurisdiction", tokenstore.JurisdictionService("https://eu.example")},
	} {
		if v, err := tokenstore.Get(probe.service, "alice"); !errors.Is(err, tokenstore.ErrNotFound) {
			t.Errorf("%s token: orphaned (value %q, err %v); want ErrNotFound", probe.label, v, err)
		}
	}
}

// Migration with a current login must keep that login's own credentials.
func TestProbe_MigrationKeepsCurrentLoginCredentials(t *testing.T) {
	cfgDir := t.TempDir()
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	svc := tokenstore.CoreKeyringService("https://core.example")
	if err := tokenstore.Set(svc, "alice", "access-token"); err != nil {
		t.Fatalf("seed: %v", err)
	}
	data, err := json.Marshal(contexts.File{
		CurrentContext: "core.example",
		Contexts: []*contexts.Context{{
			Name: "core.example", CoreURL: "https://core.example",
			Handle: "alice", KeychainService: svc,
		}},
	})
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if err := os.WriteFile(filepath.Join(cfgDir, "contexts.json"), data, 0o600); err != nil {
		t.Fatalf("write legacy: %v", err)
	}

	f, err := contexts.Load(cfgDir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if got := f.Find(f.CurrentContext); got == nil || got.Handle != "alice" {
		t.Fatalf("migrated login = %+v, want alice", got)
	}
	if v, err := tokenstore.Get(svc, "alice"); err != nil || v != "access-token" {
		t.Fatalf("current login token = %q, %v; want it preserved", v, err)
	}
}

