39	// RememberJurisdictionAudience adds audience to context `name`'s
40	// JurisdictionAudiences, so logout can find the matching keyring slot.
41	// Idempotent: an already-recorded audience rewrites nothing.
42	//
43	// Callers MUST record before writing the token to the credential store — a
44	// persisted-but-unrecorded token is a bearer logout can't find, whereas a
45	// failed record that aborts the write costs only one token exchange.
46	func RememberJurisdictionAudience(name, audience string) error {
47		aud := strings.TrimRight(strings.TrimSpace(audience), "/")
48		if name == "" || aud == "" {
49			return errors.New("context name and jurisdiction audience are both required")
50		}
51		if err := contexts.Modify(userdirs.Config(), func(f *contexts.File) (bool, error) {
52			c := f.Find(name)
53			if c == nil {
54				return false, fmt.Errorf("no login context named %q", name)
55			}
56			if slices.Contains(c.JurisdictionAudiences, aud) {
57				return false, nil
58			}
59			c.JurisdictionAudiences = append(c.JurisdictionAudiences, aud)
60			return true, nil
61		}); err != nil {
62			return fmt.Errorf("record jurisdiction audience %q for context %q: %w", aud, name, err)
63		}
64		return nil
65	}
66	
67	// removeContextLocked deletes the context selected by pick — keyring slots
68	// first, then the contexts.json entry — inside a single locked Modify, so
69	// selection, credential deletion, and entry removal can't interleave with a
70	// concurrent `auth use` or login. A nil pick result is a no-op.
71	//
72	// Credential deletion comes first and is part of the success contract:
73	// removing the entry and then failing the keyring delete would report
74	// "Logged out." while the long-lived refresh token survives on the machine,
75	// mintable by any keyring-capable process. A delete error aborts the Modify,
76	// leaving the entry intact for a retry. The inverse partial failure (slots
77	// deleted, entry write fails) is benign — the context reads as not logged in
78	// and a retried logout no-ops the deletes.
79	func removeContextLocked(pick func(*contexts.File) *contexts.Context) error {
80		//nolint:wrapcheck // callers wrap with their own operation context
81		return contexts.Modify(userdirs.Config(), func(f *contexts.File) (bool, error) {
82			c := pick(f)
83			if c == nil {
84				return false, nil
85			}
86			if err := deleteContextKeychain(c); err != nil {
87				return false, fmt.Errorf("remove credentials for %q: %w", c.Name, err)
88			}
89			f.Delete(c.Name)
90			return true, nil
91		})
92	}
93	
94	// deleteContextKeychain removes every keyring slot a context owns: the paired
95	// refresh + access tokens, plus one jurisdiction (data-plane) access token per
96	// recorded audience — each of those authorizes git against every repo the
97	// account can reach. A missing entry is fine; any other failure surfaces so
98	// logout doesn't claim success over surviving credentials.
99	//
100	// Deletion runs longest-lived-first — refresh (indefinite), jurisdiction (8h),
101	// access (an hour at most) — so a mid-sequence failure leaves behind only the
102	// shorter-lived credential. Unrecorded jurisdiction slots are unreachable (no
103	// enumeration API) and left to expire.
104	func deleteContextKeychain(c *contexts.Context) error {
105		if c == nil || c.Handle == "" {
106			return nil
107		}
108		if c.KeychainService != "" {
109			if err := tokenstore.Delete(tokenstore.RefreshService(c.KeychainService), c.Handle); err != nil && !errors.Is(err, tokenstore.ErrNotFound) {
110				return fmt.Errorf("delete refresh token: %w", err)
111			}
112		}
113		for _, audience := range c.JurisdictionAudiences {
114			// A blank entry can only come from a hand-edited or corrupted
115			// contexts.json, and would resolve to the bare service prefix — no
116			// token lives there, so skip rather than round-trip the keyring.
117			if strings.TrimSpace(audience) == "" {
118				continue
119			}
120			if err := tokenstore.Delete(tokenstore.JurisdictionService(audience), c.Handle); err != nil && !errors.Is(err, tokenstore.ErrNotFound) {
121				return fmt.Errorf("delete jurisdiction token for %s: %w", audience, err)
122			}
123		}
124		if c.KeychainService != "" {
125			if err := tokenstore.Delete(c.KeychainService, c.Handle); err != nil && !errors.Is(err, tokenstore.ErrNotFound) {
126				return fmt.Errorf("delete access token: %w", err)
127			}
128		}
129		return nil
130	}
131	
132	// SetCurrentContext makes name the active context. Returns an error when
133	// no context with that name exists (a stale current pointer is a foot-gun).
134	func SetCurrentContext(name string) error {
135		if err := contexts.Modify(userdirs.Config(), func(f *contexts.File) (bool, error) {
136			if f.Find(name) == nil {
137				return false, fmt.Errorf("no login context named %q (run `entire auth contexts` to list)", name)
138			}
139			if f.CurrentContext == name {
140				return false, nil
141			}
142			f.CurrentContext = name
143			return true, nil
144		}); err != nil {
145			return fmt.Errorf("set current context: %w", err)
146		}
147		return nil
148	}
149	
150	// Contexts returns all stored login contexts and the current context name,
151	// for listing/switching. Order matches on-disk order.
152	func Contexts() ([]*contexts.Context, string, error) {
153		f, err := contexts.Load(userdirs.Config())
154		if err != nil {
155			return nil, "", fmt.Errorf("load contexts: %w", err)
156		}
157		return f.Contexts, f.CurrentContext, nil
158	}

