44	// completeContextNames is the ValidArgsFunction for commands taking a single
45	// <context> positional. It offers the stored context names, each annotated
46	// (shell-completion descriptions, after a tab) with handle, core URL, and an
47	// "(active)" marker for the current context. Errors are swallowed because
48	// completion runs on every TAB press; a failed read just yields no suggestions.
49	func completeContextNames(_ *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
50		if len(args) != 0 {
51			// <context> is a single positional; nothing to complete past it.
52			return nil, cobra.ShellCompDirectiveNoFileComp
53		}
54		all, current, err := auth.Contexts()
55		if err != nil {
56			return nil, cobra.ShellCompDirectiveNoFileComp
57		}
58		out := make([]string, 0, len(all))
59		for _, c := range all {
60			desc := c.Handle
61			if c.CoreURL != "" {
62				desc += " " + c.CoreURL
63			}
64			if c.Name == current {
