98	// renderContextsTable prints the saved login contexts as a styled, aligned
99	// table with column headers. The active context is flagged with "*" in the
100	// leading column. Purely local data — no network, no timestamps — so it
101	// reuses the auth-table styles but only the header/name/value/accent slots.
102	func renderContextsTable(w io.Writer, all []*contexts.Context, current string) {
103		sty := newAuthTableStyles(w)
104	
105		header := []string{
106			"", // active marker
107			sty.render(sty.header, "CONTEXT"),
108			sty.render(sty.header, "HANDLE"),
109			sty.render(sty.header, "LOGIN SERVER"),
110		}
111	
112		rows := make([][]string, 0, len(all))
113		for _, c := range all {
114			marker := " "
115			name := sty.render(sty.value, c.Name)
116			if c.Name == current {
117				marker = sty.render(sty.id, "*")
118				name = sty.render(sty.name, c.Name)
119			}
120			rows = append(rows, []string{
121				marker,
122				name,
123				sty.render(sty.value, fallback(c.Handle, placeholderDash)),
124				sty.render(sty.value, fallback(c.CoreURL, placeholderDash)),
125			})
126		}
127	
128		renderAlignedTable(w, header, rows)
129	}

